{
  "program": "atomic_counter_two_workers",
  "version": "3.5.0",
  "entry": "main::main",
  "modules": [
    {
      "name": "main",
      "provides": {
        "resources": ["c"],
        "functions": ["main", "w1", "w2"]
      },
      "requires": {
        "resources": [],
        "functions": []
      },
      "resources": [
        {
          "name": "c",
          "kind": "var",
          "type": "Atomic",
          "base": "Int",
          "init": 0
        }
      ],
      "protection": [],
      "functions": [
        {
          "name": "main",
          "kind": "normal",
          "body": [
            {"sid": "s1", "kind": "spawn", "func": "main::w1", "handle": "h1"},
            {"sid": "s2", "kind": "spawn", "func": "main::w2", "handle": "h2"},
            {"sid": "s3", "kind": "join", "handle": "h1"},
            {"sid": "s4", "kind": "join", "handle": "h2"},
            {"sid": "s5", "kind": "return"}
          ]
        },
        {
          "name": "w1",
          "kind": "normal",
          "form": "closure",
          "locals": [
            {"name": "expect", "type": "Int", "modeled": true, "init": 0},
            {"name": "desired", "type": "Int", "modeled": true, "init": 0},
            {"name": "ok", "type": "Bool", "modeled": true, "init": false}
          ],
          "body": [
            {"sid": "s1", "kind": "assign_local", "target": "ok", "expr": "false"},
            {"sid": "s2", "kind": "atomic_load", "resource": "main::c", "dst": "expect"},
            {"sid": "s3", "kind": "assign_local", "target": "desired", "expr": "expect + 1"},
            {
              "sid": "s4",
              "kind": "atomic_cas",
              "resource": "main::c",
              "expected": "expect",
              "desired": "desired",
              "dst": "ok"
            },
            {"sid": "s5", "kind": "branch", "cond": "ok == false", "then": "s2", "else": "s6"},
            {"sid": "s6", "kind": "return"}
          ]
        },
        {
          "name": "w2",
          "kind": "normal",
          "form": "closure",
          "locals": [
            {"name": "expect", "type": "Int", "modeled": true, "init": 0},
            {"name": "desired", "type": "Int", "modeled": true, "init": 0},
            {"name": "ok", "type": "Bool", "modeled": true, "init": false}
          ],
          "body": [
            {"sid": "s1", "kind": "assign_local", "target": "ok", "expr": "false"},
            {"sid": "s2", "kind": "atomic_load", "resource": "main::c", "dst": "expect"},
            {"sid": "s3", "kind": "assign_local", "target": "desired", "expr": "expect + 1"},
            {
              "sid": "s4",
              "kind": "atomic_cas",
              "resource": "main::c",
              "expected": "expect",
              "desired": "desired",
              "dst": "ok"
            },
            {"sid": "s5", "kind": "branch", "cond": "ok == false", "then": "s2", "else": "s6"},
            {"sid": "s6", "kind": "return"}
          ]
        }
      ]
    }
  ]
}
